CREATE TABLE IF NOT EXISTS members(id IDENTITY PRIMARY KEY,member_number VARCHAR(30) UNIQUE NOT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(200) UNIQUE NOT NULL,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id IDENTITY PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(300) NOT NULL,role VARCHAR(20) NOT NULL,member_id BIGINT UNIQUE REFERENCES members(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash VARCHAR(64) PRIMARY KEY,user_id BIGINT REFERENCES users(id),expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id IDENTITY PRIMARY KEY,member_id BIGINT UNIQUE NOT NULL REFERENCES members(id),balance DECIMAL(14,2) DEFAULT 0 CHECK(balance>=0),updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger(id IDENTITY PRIMARY KEY,account_id BIGINT NOT NULL REFERENCES accounts(id),type VARCHAR(12) NOT NULL,amount DECIMAL(14,2) NOT NULL CHECK(amount>0),reference VARCHAR(80) UNIQUE NOT NULL,performed_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
